/// The alphabet an entity-set identifier is constrained to: the `[A-Za-z0-9]+`
/// GuardDuty publishes in the constraint refusal it answers for a
/// `threatEntitySetId` or a `trustedEntitySetId` outside it.
///
/// The model targets both members at the unconstrained `String`
/// (`smithy_query(operation="GetThreatEntitySet")`), so the boundary validator
/// never sees this constraint and a value that cannot be an identifier at all
/// reaches the handler; the service enforces it there, which is why
/// [`entity_set_id_constraint_rejection`] lives beside this constant rather than in
/// the framework's own refusal path. Every identifier this service mints is
/// hexadecimal, so a stored id always satisfies it.
pub const ENTITY_SET_ID_PATTERN: &str = "[A-Za-z0-9]+";

/// Does `id` satisfy [`ENTITY_SET_ID_PATTERN`] — one or more ASCII letters and
/// digits, and nothing else?
///
/// Form only: an identifier of the right form need not name a set that exists,
/// which is a different question with a different answer
/// ([`ENTITY_SET_NOT_FOUND_MESSAGE`]).
fn is_entity_set_id(id: &str) -> bool {
    !id.is_empty() && id.bytes().all(|byte| byte.is_ascii_alphanumeric())
}

/// `Some(message)` when `id` breaks the pattern the `member` that carried it is
/// constrained to, `None` when it satisfies it.
///
/// The message is the FRAMEWORK's: the violation is handed to
/// [`::aws_smithy_schema_server::envelope`], which states how many violations were
/// detected and renders the clause — the member path the request spelled and the
/// pattern the value had to satisfy — so this constraint is worded exactly like the
/// ones the model declares and the boundary validator finds, and no sentence is
/// spelled here. The violation is marked as one whose value is withheld, because the
/// requirement is the pattern and not the one value that missed it, so nothing of the
/// caller's value is echoed back.
///
/// One classifier for every operation that carries an entity-set identifier — the
/// read, the update and the delete of both the threat and the trusted family — so
/// the constraint cannot drift between them.
pub fn entity_set_id_constraint_rejection(member: &str, id: &str) -> Option<String> {
    if is_entity_set_id(id) {
        return None;
    }
    ::aws_smithy_schema_server::envelope(&[::aws_smithy_schema_server::Violation {
        path: member.to_string(),
        kind: ::aws_smithy_schema_server::ViolationKind::Pattern(
            ENTITY_SET_ID_PATTERN.to_string(),
        ),
        value: None,
        sensitive: true,
    }])
}

/// The error CLASS GuardDuty rejects an unacceptable request input with.
///
/// GuardDuty's model folds every client rejection into the single
/// `BadRequestException` envelope (`httpError` 400, members `message` and `type`,
/// "The error type"), but the service answers with the specific class: the body
/// carries it in BOTH the `__type` discriminator and the exception's own `type`
/// member, so a client switching on the error type can tell an unacceptable input
/// from any other 400. See [`ClassifiedError`].
pub const INVALID_INPUT_EXCEPTION: &str = "InvalidInputException";

/// The modeled error SHAPE every one of this service's client rejections is
/// enveloped in: the only client error bound to its operations
