///
/// restJson1 resolves the error shape from the `x-amzn-errortype` header rather
/// than from the body, so that header names the SHAPE while the body's `__type`
/// names the class. The two differ on purpose: an SDK needs the shape to
/// unmarshal the response into, and the client needs the class to switch on.
pub const BAD_REQUEST_EXCEPTION: &str = "BadRequestException";

/// The modeled error SHAPE an authorization refusal is enveloped in: the client
/// error every operation restricted to a standing declares beside
/// [`BAD_REQUEST_EXCEPTION`] (`smithy_query(operation="CreateCustomDetectionRuleOrgConfiguration")`).
///
/// restJson1 resolves the error shape from `x-amzn-errortype`, so this is the name
/// that header carries for a caller the operation is not available to, while the
/// body's `__type` and `type` carry the [`INVALID_INPUT_EXCEPTION`] class — the
/// same split [`Scaffolded::invalid_input`] makes between the shape an SDK
/// unmarshals into and the class a client switches on.
pub const ACCESS_DENIED_EXCEPTION: &str = "AccessDeniedException";

/// The message a caller that does not hold the standing an operation requires is
/// refused with.
///
/// Entirely FIXED text: it names neither the operation, nor the account, nor the
/// standing that is missing, because the one fact it reports is that the caller may
/// not make this call at all — telling it anything more about the organization
/// would answer a question it is not authorized to ask.
pub const NOT_AUTHORIZED_MESSAGE: &str =
    "The request is rejected because the caller is not authorized to call this API.";

/// The message an operation that reports the GuardDuty DELEGATED ADMINISTRATOR's own
/// configuration refuses a request with when the organization the endpoint serves has
/// no delegated administrator enabled.
///
/// `DescribeOrganizationConfiguration` "returns information about the account
/// selected as the delegated administrator for GuardDuty"
/// (`smithy_query(query="doc",shape="DescribeOrganizationConfiguration")`): with no
/// account selected there is no such information, so the request is refused rather
/// than answered with a configuration nobody administers. Entirely FIXED text — it
/// names neither the account nor the Region, because the one fact it reports is that
/// the precondition is missing.
///
/// It is a DIFFERENT refusal from [`NOT_AUTHORIZED_MESSAGE`], which answers a caller
/// that may not make a call the organization's delegated administrator may: this one
/// says the organization has no delegated administrator at all.
pub const DELEGATED_ADMINISTRATOR_NOT_ENABLED_MESSAGE: &str =
    "The request failed because a delegated administrator account has not been enabled.";

/// The error CLASS GuardDuty names a request it refuses because work it collides
/// with is already running.
///
/// The service's own server error shape (`httpError` 500,
/// `smithy_query(shape="InternalServerErrorException")`), and a modelled error of
/// the operations that answer it — but the refusal carries the status of a request
/// the service will not perform rather than the shape's own, because nothing
/// failed on the server: see [`Scaffolded::in_progress`].
pub const INTERNAL_SERVER_ERROR_EXCEPTION: &str = "InternalServerErrorException";

/// The error CLASS GuardDuty names a request that addresses a resource the
/// service does not hold, on the families whose absence refusal is a 404.
///
/// A modelled shape of this service (`httpError` 404, members `message` and
/// `type` — `smithy_query(shape="ResourceNotFoundException")`), so an SDK
